import React from "react";
import type { StickerProps } from "../../types";
import { AnimatedSticker } from "../../components/AnimatedSticker";

// Exact reference pixels embedded as a lossless PNG — same technique as CatbeatsSticker.
const IMAGE = "data:image/png;base64,";

/**
 * Spooky Ghost Sticker — reproduced from the original Dribbble reference artwork.
 * Text, if any, is baked into the artwork and is not configurable.
 */
export const SpookyGhostSticker: React.FC<StickerProps> = (props) => (
  <AnimatedSticker
    {...props}
    label="Spooky Ghost Sticker"
    viewBox="0 0 277 291"
    motion="float"
    duration={3.8}
    origin="139px 291px"
  >
    <image href={IMAGE} x={0} y={0} width={277} height={291} />
  </AnimatedSticker>
);

export default SpookyGhostSticker;
